 1	/**
 2	 * Scoped to this atom's own contract per testing.md: given a value or no value, does it render
 3	 * the right branch, and does the label reach the DOM as microcopy rather than a prop.
 4	 *
 5	 * The recipe's own resolution is covered by theme/components/recipeGuards.test.ts and
 6	 * ui-kits/recipeParts.test.ts; the visual result is covered by index.stories.tsx. Neither of
 7	 * those proves the absent-value branch is discoverable from this folder, which is what this is.
 8	 */
 9	import React from 'react';
10	import { describe, test, expect, vi } from 'vitest';
11	import { render, screen } from '@testing-library/react';
12	import { ZimmProductStyleCode } from './index';
13	
14	describe('ZimmProductStyleCode', () => {
15	  test('renders the label and value as one readable line', () => {
16	    render(<ZimmProductStyleCode value="8637DS241" />);
17	    // The DS models label and value as two nodes; a screen reader and a copy-paste must still
18	    // see the single string both composed page designs show.
19	    expect(screen.getByTestId('product-style-code').textContent).toBe('Style Code: 8637DS241');
20	  });
21	
22	  test.each([undefined, ''])('renders nothing for %s', (value) => {
23	    render(<ZimmProductStyleCode value={value} />);
24	    // The page places this unconditionally, so an absent style code must collapse rather than
25	    // leave an empty styled node contributing to the stack's rhythm.
26	    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
27	  });
28	
29	  test('takes the label from useUiCopy, not a hardcoded string', async () => {
30	    // Proves the copy is actually looked up: a CMS override must win over the fallback. If the
31	    // label were inlined this passes vacuously, so the assertion is on the overridden value.
32	    vi.doMock('app/hooks/useUiCopy', () => ({
33	      useUiCopy: () => ({ t: (_key: string) => 'Código de estilo:', isLoading: false }),
34	    }));
35	    vi.resetModules();
36	    const { ZimmProductStyleCode: Localised } = await import('./index');
37	
38	    render(<Localised value="8637DS241" />);
39	    expect(screen.getByTestId('product-style-code').textContent).toBe('Código de estilo: 8637DS241');
40	    vi.doUnmock('app/hooks/useUiCopy');
41	  });
42	});

