import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';

// Hardcoded UI copy, not a prop and not a CMS lookup — see the note on the component below.
// Named rather than inlined so the string sits at the top of the file, the same way
// zimmSubscribeModal/index.tsx keeps PRIVACY_CONSENT_COPY and ACCESSIBILITY_DISCLAIMER_COPY.
const LABEL = 'Style Code:';

type ZimmProductStyleCodeProps = {
  /**
   * The master product's style number. This is the style code shown to shoppers, which is not
   * the same value as the variant `product.id`.
   */
  value?: string;
};

/**
 * Atom — the "Style Code: 7300JS261" line. Renders nothing when no style code is available.
 *
 * The label is the hardcoded LABEL constant above rather than CMS microcopy: useContentful.ts
 * requests entries with no `locale` parameter, so a `uiCopy` lookup would serve the space
 * default to all eight storefronts regardless of site. zimmSubscribeModal/index.tsx hardcodes
 * its copy the same way.
 */
export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
  const styles = useMultiStyleConfig('ZimmProductStyleCode', {});
  if (!value) return null;

  return (
    <chakra.div __css={styles.root} textStyle="caption" data-testid="product-style-code">
      <chakra.span __css={styles.label}>{LABEL}</chakra.span>
      {/*
        A real space so `textContent` — what a screen reader reads out and what a shopper
        copies — is "Style Code: 8637DS241", matching both composed page designs. It adds no
        visual width: a whitespace-only anonymous flex item is not rendered (CSS Flexbox §4),
        so the 4px `gap` in the recipe remains the only spacing.
      */}{' '}
